def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping the high bits around.

    x must be in 0..255 and k in 0..7. The result is also in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_simple_wrap() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b10110001, 3) == 0b10001101


def test_rotl8_nibble_swap() -> None:
    assert rotl8(0x0F, 4) == 0xF0
    assert rotl8(0xA5, 4) == 0x5A


def test_rotl8_zero_shift_is_identity() -> None:
    for x in range(256):
        assert rotl8(x, 0) == x


def test_rotl8_max_shift() -> None:
    assert rotl8(0b00000001, 7) == 0b10000000
    assert rotl8(0b10000000, 7) == 0b01000000


def test_rotl8_fixed_points() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255


def test_rotl8_matches_string_rotation() -> None:
    for x in range(256):
        s = format(x, "08b")
        for k in range(8):
            expected = int(s[k:] + s[:k], 2)
            assert rotl8(x, k) == expected


def test_rotl8_result_in_range_and_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            r = rotl8(x, k)
            assert 0 <= r <= 255
            assert bin(r).count("1") == bin(x).count("1")


def test_rotl8_inverse_by_complementary_shift() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(rotl8(x, k), (8 - k) % 8) == x
